<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'

const activeView = ref('Sơ đồ bàn')
const selectedTable = ref('Bàn 06')
const selectedTableId = ref('')
const showOrder = ref(false)
const sidebarOpen = ref(false)
const showTablePicker = ref(false)
const showReceipt = ref(false)
const showQr = ref(false)
const showKdsOrder = ref(false)
const selectedKdsOrder = ref(null)
const paymentSuccess = ref(null)
const readyOrderIds = ref(new Set())
const readyTrackingStarted = ref(false)
const billRequestIds = ref(new Set())
const billTrackingStarted = ref(false)
const notificationsEnabled = ref(typeof Notification !== 'undefined' && Notification.permission === 'granted')
const currentOrder = ref(null)
const paymentSettings = ref({ bankId:'', accountNumber:'', accountName:'' })
const paymentSettingsEditing = ref(false)
const toast = ref('')
const tables = ref([])
const orders = ref([])
const menu = ref([])
const toppings = ref([])
const draftCarts = ref({})
const cart = computed({
  get: () => selectedTableId.value ? (draftCarts.value[selectedTableId.value] ||= []) : [],
  set: value => { if (selectedTableId.value) draftCarts.value[selectedTableId.value] = value }
})
const itemUnitPrice = item => item.price + (item.selectedToppings || []).reduce((sum,id)=>sum+(toppings.value.find(t=>t.id===id)?.price||0),0)
const cartTotal = computed(() => cart.value.reduce((total, item) => total + itemUnitPrice(item) * item.qty, 0))
const formattedTotal = computed(() => new Intl.NumberFormat('vi-VN').format(cartTotal.value) + 'đ')
// Dùng cùng origin với giao diện; Vite chuyển tiếp /api tới backend trung tâm.
// Cách này tránh lỗi CORS/cổng 3032 trên điện thoại và tablet trong LAN.
const apiUrl = import.meta.env.VITE_API_URL || '/api'
const savedToken = localStorage.getItem('coffee_token') || ''
function jwtExpired(value){try{const part=value.split('.')[1].replace(/-/g,'+').replace(/_/g,'/');const payload=JSON.parse(atob(part+'='.repeat((4-part.length%4)%4)));return !payload.exp||payload.exp*1000<=Date.now()}catch{return true}}
const token = ref(savedToken && !jwtExpired(savedToken) ? savedToken : '')
if(!token.value){localStorage.removeItem('coffee_token');localStorage.removeItem('coffee_user')}
const loginForm = ref({ email: '', password: '' })
const loginError = ref('')
const signingIn = ref(false)
const licenseStatus = ref(null)
const licenseKey = ref('')
const licenseError = ref('')
const activatingLicense = ref(false)
const currentUser = ref(JSON.parse(localStorage.getItem('coffee_user') || 'null') || (token.value ? { name: 'Tài khoản quản trị', role: 'owner' } : null))
const newProduct = ref({ name: '', price: '' })
const newTopping = ref({ productId:'', name:'', price:'' })
const newTable = ref({ name: '', seats: 2, areaId:'', shape:'rectangle' })
const showTableForm = ref(false)
const areas = ref([])
const selectedAreaId = ref('')
const newArea = ref({name:'',canvasWidth:1000,canvasHeight:600})
const showAreaForm = ref(false)
const layoutSelectedTable = ref(null)
const activeArea = computed(() => areas.value.find(a=>a.id===selectedAreaId.value) || areas.value[0] || null)
const areaTables = computed(() => selectedAreaId.value ? tables.value.filter(t=>t.areaId===selectedAreaId.value) : tables.value)
const allOrders = ref([])
const users = ref([])
const report = ref({ revenue:0, paidOrders:0, cancelledOrders:0 })
const promotions = ref([])
const customers = ref([])
const currentShift = ref(null)
const shiftHistory = ref([])
const operationsReport = ref({cancellations:[],staffPerformance:[]})
const ingredients = ref([])
const suppliers = ref([])
const stockReceipts = ref([])
const inventoryReport = ref({summary:{ingredientCount:0,lowStockCount:0,stockValue:0},movements:[],costs:{wasteCost:0,consumptionCost:0}})
const newIngredient = ref({code:'',name:'',category:'',unit:'g',reorderLevel:0})
const newSupplier = ref({name:'',phone:'',address:'',note:''})
const receiptForm = ref({supplierId:'',note:'',items:[{ingredientId:'',quantity:1,unitCost:0}]})
const adjustmentForm = ref({ingredientId:'',quantityChange:'',reason:''})
const countNote = ref('')
const physicalCounts = ref({})
const recipeOwner = ref({kind:'product',id:''})
const recipeItems = ref([])
const newPromotion = ref({code:'',name:'',type:'percent',value:'',minimumOrder:0,maximumDiscount:''})
const shiftCash = ref('')
const promoCode = ref('')
const customerForm = ref({name:'',phone:''})
const selectedCustomer = ref(null)
const redeemPointsValue = ref('')
const showTransfer = ref(false)
const transferTargetId = ref('')
const mergeTarget = ref(false)
const layoutEditing = ref(false)
const dragTable = ref(null)
const printerSettings = ref({printerName:'',autoPrint:false,openCashDrawer:false})
const newUser = ref({ name:'', email:'', password:'', role:'server' })
const roleNames = { owner: 'Chủ cửa hàng', manager: 'Quản lý cửa hàng', cashier: 'Thu ngân', server: 'Phục vụ', barista: 'Pha chế' }
const roleViews = {
  owner: ['Tổng quan','Thu ngân POS','Sơ đồ bàn','Đơn hàng','Pha chế · KDS','Menu & danh mục','Kho nguyên liệu','Khuyến mãi & khách hàng','Ca làm & đối soát','Báo cáo doanh thu','Nhân sự & phân quyền'],
  manager: ['Tổng quan','Thu ngân POS','Sơ đồ bàn','Đơn hàng','Pha chế · KDS','Menu & danh mục','Kho nguyên liệu','Khuyến mãi & khách hàng','Ca làm & đối soát','Báo cáo doanh thu'],
  cashier: ['Thu ngân POS','Đơn hàng','Ca làm & đối soát'],
  server: ['Phục vụ bàn'],
  barista: ['Pha chế · KDS']
}
const operationalNav = computed(() => ['Tổng quan','Phục vụ bàn','Thu ngân POS','Sơ đồ bàn','Đơn hàng','Pha chế · KDS','Ca làm & đối soát'].filter(view => roleViews[currentUser.value?.role]?.includes(view)))
const managementNav = computed(() => ['Menu & danh mục','Kho nguyên liệu','Khuyến mãi & khách hàng','Báo cáo doanh thu','Nhân sự & phân quyền'].filter(view => roleViews[currentUser.value?.role]?.includes(view)))
const userInitials = computed(() => (currentUser.value?.name || 'Admin').split(' ').slice(-2).map(x => x[0]).join('').toUpperCase())
const itemStatusNames = { sent:'Chờ pha', preparing:'Đang pha', ready:'Sẵn sàng trả', served:'Đã giao', paid:'Đã thanh toán', cancelled:'Đã hủy' }
const qrUrl = computed(() => currentOrder.value && paymentSettings.value.bankId ? `https://img.vietqr.io/image/${encodeURIComponent(paymentSettings.value.bankId)}-${encodeURIComponent(paymentSettings.value.accountNumber)}-compact2.png?amount=${currentOrder.value.total}&addInfo=${encodeURIComponent('HD'+currentOrder.value.orderNumber)}&accountName=${encodeURIComponent(paymentSettings.value.accountName)}` : '')
const statusTone = { available: 'free', occupied: 'busy', payment_requested: 'payment-requested', ordering: 'ordering', reserved: 'reserved' }
const formatReceiptDate = value => new Intl.DateTimeFormat('vi-VN', {
  timeZone:'Asia/Ho_Chi_Minh', hour:'2-digit', minute:'2-digit',
  day:'2-digit', month:'2-digit', year:'numeric'
}).format(new Date(value))
async function api(path, options = {}) {
  let response
  try { response = await fetch(`${apiUrl}${path}`, { ...options, headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token.value}`, ...(options.headers || {}) } }) }
  catch { const error=new Error('Không kết nối được API. Hãy mở trang bằng Chrome/Safari thay vì Messenger.');error.status=0;throw error }
  const raw = await response.text()
  const data = raw ? JSON.parse(raw) : null
  if (!response.ok) {
    const error = new Error(data?.error || (response.status===401?'Phiên đăng nhập không còn hợp lệ.':'Không thể kết nối máy chủ.'))
    error.status = response.status
    if(response.status===401&&path!=='/auth/login'&&token.value){logout();loginError.value='Phiên đăng nhập đã hết hạn hoặc máy chủ vừa được cập nhật. Vui lòng đăng nhập lại.'}
    throw error
  }
  return data
}
async function loadData() {
  const canReport = ['owner','manager','cashier'].includes(currentUser.value?.role)
  const [tableResult, menuResult, toppingResult, kdsResult, settingsResult, historyResult, reportResult, areaResult] = await Promise.allSettled([api('/tables'), api('/products'), api('/toppings'), api('/orders/kds'), api('/payment-settings'), api('/orders'), canReport ? api('/reports/summary') : Promise.resolve({ revenue:0, paidOrders:0, cancelledOrders:0 }),api('/areas')])
  const failedAuth = [tableResult,menuResult,toppingResult,kdsResult,settingsResult,historyResult,reportResult,areaResult].find(result => result.status === 'rejected' && result.reason?.status === 401)
  if (failedAuth) throw failedAuth.reason
  // Không để nhịp đồng bộ 2 giây ghi đè nội dung quản lý đang nhập.
  if (settingsResult.status === 'fulfilled' && !paymentSettingsEditing.value) paymentSettings.value = settingsResult.value
  if (historyResult.status === 'fulfilled') {
    allOrders.value = historyResult.value
    const requestedNow=new Set(allOrders.value.filter(o=>o.billRequestedAt&&!['paid','cancelled'].includes(o.status)).map(o=>o.id))
    if(['owner','cashier'].includes(currentUser.value?.role)&&billTrackingStarted.value)allOrders.value.filter(o=>o.billRequestedAt&&!billRequestIds.value.has(o.id)&&!['paid','cancelled'].includes(o.status)).forEach(alertBillRequest)
    billRequestIds.value=requestedNow;billTrackingStarted.value=true
  }
  if (reportResult.status === 'fulfilled') report.value = reportResult.value
  if (areaResult.status === 'fulfilled') { areas.value=areaResult.value;if(!areas.value.some(a=>a.id===selectedAreaId.value))selectedAreaId.value=areas.value[0]?.id||'';if(!newTable.value.areaId)newTable.value.areaId=selectedAreaId.value }
  if (tableResult.status === 'fulfilled') tables.value = tableResult.value.map(t => ({ ...t, tone: statusTone[t.status] || 'free', status: { available:'Trống', occupied:'Đang dùng', payment_requested:'Chờ thanh toán', ordering:'Đang gọi món', reserved:'Đặt trước' }[t.status] || t.status, bill: t.total ? new Intl.NumberFormat('vi-VN').format(t.total) + 'đ' : '', time: t.openedAt ? 'Đang phục vụ' : '' }))
  if (menuResult.status === 'fulfilled') menu.value = menuResult.value.map(p => ({ ...p, id:p.id ?? p.Id, name:p.name ?? p.Name, isAvailable:p.isAvailable ?? true, emoji:'☕' }))
  if (toppingResult.status === 'fulfilled') toppings.value = toppingResult.value
  if (kdsResult.status === 'fulfilled') {
    orders.value = kdsResult.value.map(o => ({ id:'#' + (o.orderNumber ?? o.OrderNumber), orderId:o.id ?? o.Id, table:o.tableName || 'Mang đi', items:`${o.itemCount} món`, time:new Date(o.openedAt ?? o.OpenedAt).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}), status:o.status ?? o.Status, state:{sent:'Chờ pha',preparing:'Pha chế',ready:'Sẵn sàng'}[o.status ?? o.Status], color:{sent:'purple',preparing:'amber',ready:'green'}[o.status ?? o.Status] }))
    const readyNow=new Set(orders.value.filter(o=>o.status==='ready').map(o=>o.orderId))
    if(currentUser.value?.role==='server'&&readyTrackingStarted.value)orders.value.filter(o=>o.status==='ready'&&!readyOrderIds.value.has(o.orderId)).forEach(alertReadyOrder)
    readyOrderIds.value=readyNow;readyTrackingStarted.value=true
  }
  if(['owner','manager','cashier'].includes(currentUser.value?.role)&&['Thu ngân POS','Ca làm & đối soát'].includes(activeView.value))try{currentShift.value=await api('/shifts/current')}catch{}
  // Giữ chi tiết đang mở đồng bộ với thao tác ở KDS/thu ngân/phục vụ trên máy khác.
  if(currentOrder.value?.id&&(showOrder.value||showReceipt.value))try{currentOrder.value=await api(`/orders/${currentOrder.value.id}`)}catch{}
  if(selectedKdsOrder.value?.id&&showKdsOrder.value)try{selectedKdsOrder.value=await api(`/orders/${selectedKdsOrder.value.id}`)}catch{}
}
async function login() {
  loginError.value = ''; signingIn.value = true
  try { const result = await api('/auth/login', { method:'POST', headers:{}, body:JSON.stringify(loginForm.value) }); token.value = result.token; currentUser.value = result.user; activeView.value = roleViews[result.user.role]?.[0] || 'Tổng quan'; localStorage.setItem('coffee_token', token.value); localStorage.setItem('coffee_user', JSON.stringify(result.user)); await loadData() }
  catch (error) { if(error.status===402)await checkLicense();loginError.value = error.status === 401 ? 'Email hoặc mật khẩu không đúng.' : (error.message || 'Không thể kết nối máy chủ.') }
  finally { signingIn.value = false }
}
function logout() { sidebarOpen.value=false;localStorage.removeItem('coffee_token'); localStorage.removeItem('coffee_user'); token.value = ''; currentUser.value = null;readyOrderIds.value=new Set();readyTrackingStarted.value=false;billRequestIds.value=new Set();billTrackingStarted.value=false }
async function checkLicense(){try{licenseStatus.value=await api('/license/status')}catch(error){licenseError.value=error.message}}
async function activateLicense(){if(!licenseKey.value.trim())return;activatingLicense.value=true;licenseError.value='';try{licenseStatus.value=await api('/license/activate',{method:'POST',body:JSON.stringify({key:licenseKey.value.trim()})});licenseKey.value='';notify('Kích hoạt bản quyền thành công')}catch(error){licenseError.value=error.message}finally{activatingLicense.value=false}}
async function copyInstallationId(){try{await navigator.clipboard.writeText(licenseStatus.value.installationId);notify('Đã sao chép mã máy')}catch{notify('Hãy giữ và gửi mã máy này cho nhà cung cấp')}}
onMounted(async () => { await checkLicense();if(!licenseStatus.value?.allowed)return;if (token.value) try { if(!roleViews[currentUser.value?.role]?.includes(activeView.value)) activeView.value=roleViews[currentUser.value?.role]?.[0]||'Tổng quan'; await loadData() } catch { logout() } })
let syncRunning=false
const syncTimer = setInterval(async () => { if(!token.value||syncRunning)return;syncRunning=true;try{await loadData()}catch(error){if(error.status===401)logout()}finally{syncRunning=false} }, 2000)
onUnmounted(() => clearInterval(syncTimer))
function addItem(item) {
  if(!item.isAvailable)return notify('Món này đang tạm hết')
  const found = cart.value.find(x => x.name === item.name)
  if (found) found.qty++
  else cart.value.push({ ...item, qty: 1, note:'', selectedToppings:[] })
}
function notify(message) { toast.value = message; setTimeout(() => toast.value = '', 2600) }
function alertReadyOrder(order) {
  const message=`${order.table}: ${order.items} đã sẵn sàng nhận tại quầy pha chế`
  notify(message);if(navigator.vibrate)navigator.vibrate([250,120,250]);if(notificationsEnabled.value&&document.hidden)new Notification('Món đã sẵn sàng',{body:message})
}
function alertBillRequest(order) {
  notify(`${order.tableName} yêu cầu in bill tạm tính`);if(navigator.vibrate)navigator.vibrate([300,100,300,100,500])
}
async function enableNotifications() {
  if(typeof Notification==='undefined')return notify('Trình duyệt này không hỗ trợ thông báo')
  const permission=await Notification.requestPermission();notificationsEnabled.value=permission==='granted';if(!notificationsEnabled.value)return notify('Bạn chưa cho phép thông báo')
  try{if(!('serviceWorker'in navigator)||!('PushManager'in window))throw new Error('Trình duyệt chưa hỗ trợ Web Push');const registration=await navigator.serviceWorker.register('/sw.js');const {publicKey}=await api('/push/public-key');const padding='='.repeat((4-publicKey.length%4)%4);const raw=atob((publicKey+padding).replace(/-/g,'+').replace(/_/g,'/'));const key=Uint8Array.from([...raw].map(c=>c.charCodeAt(0)));let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const json=subscription.toJSON();await api('/push/subscribe',{method:'POST',body:JSON.stringify({endpoint:subscription.endpoint,p256dh:json.keys.p256dh,auth:json.keys.auth})});notify('Đã bật báo món kể cả khi đóng trình duyệt')}catch(error){notificationsEnabled.value=false;notify(error.message)}
}
async function selectView(view) {
  if (!roleViews[currentUser.value?.role]?.includes(view)) return notify('Tài khoản không có quyền truy cập mục này')
  sidebarOpen.value = false
  activeView.value = view
  try {
    if (view === 'Đơn hàng') allOrders.value = await api('/orders')
    if (view === 'Báo cáo doanh thu') report.value = await api('/reports/summary')
    if (view === 'Nhân sự & phân quyền') users.value = await api('/users')
    if (view === 'Khuyến mãi & khách hàng') [promotions.value,customers.value]=await Promise.all([api('/promotions'),api('/customers')])
    if (view === 'Ca làm & đối soát') [currentShift.value,shiftHistory.value]=await Promise.all([api('/shifts/current'),api('/shifts')])
    if (view === 'Thu ngân POS') { currentShift.value=await api('/shifts/current');await loadPrinterSettings() }
    if (view === 'Báo cáo doanh thu'&&['owner','manager'].includes(currentUser.value?.role)) operationsReport.value=await api('/reports/operations')
    if (view === 'Kho nguyên liệu') await loadInventory()
  } catch (error) { notify(error.message) }
}
function openNewOrder() { if (!tables.value.length) return notify('Hãy thêm bàn trước khi tạo đơn'); showTablePicker.value = true }
async function chooseTable(table) { await openTable(table);showTablePicker.value=false }
async function openTable(table) { selectedTable.value=table.name;selectedTableId.value=table.Id || table.id;currentOrder.value=null;selectedCustomer.value=null;customerForm.value={name:'',phone:''};promoCode.value='';try{const existing=await api(`/tables/${selectedTableId.value}/order`);currentOrder.value=existing?.id?existing:null}catch(error){notify(error.message)}showOrder.value=true }
function changeQty(item, amount) { item.qty += amount; if (item.qty <= 0) cart.value = cart.value.filter(x => x !== item) }
async function createProduct() {
  if (!newProduct.value.name || Number(newProduct.value.price) < 0) return notify('Vui lòng nhập tên và giá món')
  try { await api('/products', { method: 'POST', body: JSON.stringify({ name: newProduct.value.name, price: Number(newProduct.value.price) }) }); newProduct.value = { name:'', price:'' }; await loadData(); notify('Đã thêm món mới') }
  catch (error) { notify(error.message) }
}
async function createTable() {
  try { await api('/tables', { method:'POST', body:JSON.stringify({ name:newTable.value.name, seats:Number(newTable.value.seats),areaId:newTable.value.areaId||selectedAreaId.value,shape:newTable.value.shape }) }); newTable.value={name:'',seats:2,areaId:selectedAreaId.value,shape:'rectangle'};showTableForm.value=false;await loadData();notify('Đã thêm bàn mới') } catch(error) { notify(error.message) }
}
async function createArea(){try{const result=await api('/areas',{method:'POST',body:JSON.stringify({...newArea.value,canvasWidth:Number(newArea.value.canvasWidth),canvasHeight:Number(newArea.value.canvasHeight)})});showAreaForm.value=false;newArea.value={name:'',canvasWidth:1000,canvasHeight:600};areas.value=await api('/areas');selectedAreaId.value=result.id;newTable.value.areaId=result.id;notify('Đã tạo khu vực mới')}catch(error){notify(error.message)}}
async function saveArea(){if(!activeArea.value)return;try{await api(`/areas/${activeArea.value.id}`,{method:'PATCH',body:JSON.stringify({name:activeArea.value.name,canvasWidth:Number(activeArea.value.canvasWidth),canvasHeight:Number(activeArea.value.canvasHeight)})});areas.value=await api('/areas');notify('Đã lưu kích thước khu vực')}catch(error){notify(error.message)}}
async function deleteArea(){if(!activeArea.value||!confirm(`Xóa khu vực “${activeArea.value.name}”?`))return;try{await api(`/areas/${activeArea.value.id}`,{method:'DELETE'});areas.value=await api('/areas');selectedAreaId.value=areas.value[0]?.id||'';notify('Đã xóa khu vực')}catch(error){notify(error.message)}}
async function deleteProduct(item) { if (!confirm(`Xóa món “${item.name}”?`)) return; try { await api(`/products/${item.id}`,{method:'DELETE'});await loadData();notify('Đã xóa món') } catch(error){notify(error.message)} }
async function createTopping(){try{await api('/toppings',{method:'POST',body:JSON.stringify({productId:newTopping.value.productId,name:newTopping.value.name,price:Number(newTopping.value.price)})});newTopping.value={productId:'',name:'',price:''};await loadData();notify('Đã thêm topping')}catch(error){notify(error.message)}}
async function deleteTopping(item){if(!confirm(`Xóa topping “${item.name}”?`))return;try{await api(`/toppings/${item.id}`,{method:'DELETE'});await loadData();notify('Đã xóa topping')}catch(error){notify(error.message)}}
async function toggleAvailability(item) { try { await api(`/products/${item.id}/availability`,{method:'PATCH',body:JSON.stringify({isAvailable:!item.isAvailable})});await loadData();notify(item.isAvailable?'Đã báo tạm hết món':'Đã mở bán lại món') } catch(error){notify(error.message)} }
async function cancelOrderItem(item) { if(!confirm(`Hủy món “${item.name}”? Chỉ thực hiện được khi bar chưa pha.`))return;try{await api(`/order-items/${item.id}`,{method:'DELETE'});currentOrder.value=await api(`/tables/${selectedTableId.value}/order`);await loadData();notify('Đã hủy món và cập nhật tổng tiền')}catch(error){notify(error.message)} }
async function requestBill(order) { if(order.billRequestedAt)return notify('Thu ngân đã nhận được yêu cầu');try{const result=await api(`/orders/${order.id}/request-bill`,{method:'POST'});await loadData();if(currentOrder.value?.id===order.id)currentOrder.value=await api(`/orders/${order.id}`);notify(result.printError?`Đã báo thu ngân; máy in lỗi: ${result.printError}`:`Đã gửi yêu cầu và in bill đơn #${order.orderNumber}`)}catch(error){notify(error.message)} }
async function openOrderAtTable(order){const table=tables.value.find(t=>t.name===order.tableName);if(table)await openTable(table);else await openKdsOrder({id:order.id})}
async function createPromotion(){try{await api('/promotions',{method:'POST',body:JSON.stringify({...newPromotion.value,value:Number(newPromotion.value.value),minimumOrder:Number(newPromotion.value.minimumOrder),maximumDiscount:newPromotion.value.maximumDiscount?Number(newPromotion.value.maximumDiscount):null})});newPromotion.value={code:'',name:'',type:'percent',value:'',minimumOrder:0,maximumDiscount:''};promotions.value=await api('/promotions');notify('Đã tạo khuyến mãi')}catch(error){notify(error.message)}}
async function openShift(){try{await api('/shifts/open',{method:'POST',body:JSON.stringify({openingCash:Number(shiftCash.value)})});currentShift.value=await api('/shifts/current');shiftCash.value='';shiftHistory.value=await api('/shifts');notify('Đã mở ca và bắt đầu tính doanh thu')}catch(error){notify(error.message)}}
async function closeShift(){if(!confirm(`Kết ca? Tiền dự kiến trong két là ${new Intl.NumberFormat('vi-VN').format(currentShift.value?.expectedCash||0)}đ.`))return;try{const result=await api(`/shifts/${currentShift.value.id}/close`,{method:'POST',body:JSON.stringify({closingCash:Number(shiftCash.value),note:null})});currentShift.value=null;shiftCash.value='';shiftHistory.value=await api('/shifts');notify(`Đã kết ca · doanh thu ${new Intl.NumberFormat('vi-VN').format(result.totalSales)}đ · chênh lệch két ${new Intl.NumberFormat('vi-VN').format(result.variance)}đ`)}catch(error){notify(error.message)}}
async function applyPromotion(){if(!currentOrder.value||!promoCode.value.trim())return;try{await api(`/orders/${currentOrder.value.id}/promotion`,{method:'POST',body:JSON.stringify({code:promoCode.value})});currentOrder.value=await api(`/orders/${currentOrder.value.id}`);notify('Đã áp dụng mã khuyến mãi')}catch(error){notify(error.message)}}
async function attachCustomer(){if(!currentOrder.value)return;try{const customer=await api('/customers',{method:'POST',body:JSON.stringify(customerForm.value)});await api(`/orders/${currentOrder.value.id}/customer`,{method:'POST',body:JSON.stringify({customerId:customer.id})});selectedCustomer.value=customer;redeemPointsValue.value=customer.points;customers.value=await api('/customers');notify(`Đã gắn khách ${customer.name} · ${customer.points} điểm`)}catch(error){notify(error.message)}}
async function redeemPoints(){if(!currentOrder.value)return;try{const result=await api(`/orders/${currentOrder.value.id}/redeem-points`,{method:'POST',body:JSON.stringify({points:Number(redeemPointsValue.value)})});currentOrder.value=await api(`/orders/${currentOrder.value.id}`);selectedCustomer.value.points-=result.points;notify(`Đã đổi ${result.points} điểm, giảm ${new Intl.NumberFormat('vi-VN').format(result.discount)}đ`)}catch(error){notify(error.message)}}
function openTransfer(){transferTargetId.value='';mergeTarget.value=false;showTransfer.value=true}
async function transferOrder(){if(!currentOrder.value||!transferTargetId.value)return;try{const result=await api('/tables/transfer',{method:'POST',body:JSON.stringify({orderId:currentOrder.value.id,targetTableId:transferTargetId.value,merge:mergeTarget.value})});showTransfer.value=false;showOrder.value=false;await loadData();notify(result.merged?'Đã gộp bàn và cộng đơn':'Đã đổi bàn thành công')}catch(error){notify(error.message)}}
function beginTableDrag(event,table){if(!layoutEditing.value)return;dragTable.value=table;event.dataTransfer.effectAllowed='move'}
async function dropTable(event){if(!layoutEditing.value||!dragTable.value)return;const floor=event.currentTarget.getBoundingClientRect();const width=dragTable.value.width||190,height=dragTable.value.height||120;const x=Math.max(0,Math.min((activeArea.value?.canvasWidth||1000)-width,Math.round(event.clientX-floor.left-width/2+event.currentTarget.scrollLeft)));const y=Math.max(0,Math.min((activeArea.value?.canvasHeight||600)-height,Math.round(event.clientY-floor.top-height/2+event.currentTarget.scrollTop)));dragTable.value.positionX=x;dragTable.value.positionY=y;layoutSelectedTable.value=dragTable.value;try{await saveTableLayout(dragTable.value,false);notify('Đã lưu vị trí bàn')}catch(error){notify(error.message)}finally{dragTable.value=null}}
function selectLayoutTable(table){layoutSelectedTable.value=table}
async function saveTableLayout(table=layoutSelectedTable.value,showNotice=true){if(!table)return;await api(`/tables/${table.Id||table.id}/layout`,{method:'PATCH',body:JSON.stringify({areaId:table.areaId,x:Number(table.positionX)||0,y:Number(table.positionY)||0,width:Number(table.width)||190,height:Number(table.height)||120,shape:table.shape||'rectangle'})});if(showNotice)notify('Đã lưu kiểu và kích thước bàn')}
function tableStyle(table,index){if(!layoutEditing.value)return {};const hasPosition=table.positionX||table.positionY;return {position:'absolute',left:(hasPosition?table.positionX:20+(index%4)*215)+'px',top:(hasPosition?table.positionY:20+Math.floor(index/4)*145)+'px',width:(table.width||190)+'px',height:(table.height||120)+'px'}}
function areaCanvasStyle(){return layoutEditing.value?{'--canvas-width':(activeArea.value?.canvasWidth||1000)+'px','--canvas-height':(activeArea.value?.canvasHeight||600)+'px'}:{}}
async function loadPrinterSettings(){try{printerSettings.value=await api('/printer/settings')}catch(error){notify(error.message)}}
async function savePrinterSettings(){try{printerSettings.value=await api('/printer/settings',{method:'PUT',body:JSON.stringify(printerSettings.value)});notify('Đã lưu cấu hình máy in')}catch(error){notify(error.message)}}
async function testPrinter(){try{await api('/printer/test',{method:'POST'});notify('Máy in đã nhận bản in thử')}catch(error){notify(error.message)}}
async function openCashDrawer(){try{await api('/printer/open-drawer',{method:'POST'});notify('Đã gửi lệnh mở két')}catch(error){notify(error.message)}}
async function printPhysical(){if(!currentOrder.value)return;try{await api(`/orders/${currentOrder.value.id}/print`,{method:'POST'});notify('Đã gửi bill đến máy in')}catch(error){notify(error.message)}}
async function advanceOrder(order) {
  const role=currentUser.value?.role
  let next=''
  if(order.status==='sent' && ['owner','manager','barista'].includes(role)) next='preparing'
  else if(order.status==='preparing' && ['owner','manager','barista'].includes(role)) next='ready'
  else if(order.status==='ready' && ['owner','cashier'].includes(role)) next='served'
  else return notify(order.status==='ready'?'Món đã sẵn sàng, đang chờ thu ngân xác nhận':'Đơn này đang được bộ phận pha chế xử lý')
  try { await api(`/orders/${order.orderId}/status`,{method:'PATCH',body:JSON.stringify({status:next})});await loadData();notify(next==='served'?'Đã chuyển vào lịch sử phục vụ':'Đã cập nhật KDS') } catch(error){notify(error.message)}
}
function canAdvanceOrder(order) {
  const role=currentUser.value?.role
  return (['sent','preparing'].includes(order.status)&&['owner','manager','barista'].includes(role))||(order.status==='ready'&&['owner','cashier'].includes(role))
}
function orderActionLabel(order) {
  if(order.status==='sent')return ['owner','manager','barista'].includes(currentUser.value?.role)?'Bắt đầu pha':'Đang chờ pha'
  if(order.status==='preparing')return ['owner','manager','barista'].includes(currentUser.value?.role)?'Chuyển sẵn sàng':'Đang pha chế'
  return ['owner','cashier'].includes(currentUser.value?.role)?'Xác nhận & gọi phục vụ':'Chờ thu ngân xác nhận'
}
async function openKdsOrder(order) {
  try { selectedKdsOrder.value=await api(`/orders/${order.orderId || order.id}`);showKdsOrder.value=true }
  catch(error){notify(error.message)}
}
async function advanceItem(item) {
  if(!['sent','preparing'].includes(item.status))return notify('Món đã sẵn sàng, đang chờ thu ngân xác nhận')
  const next=item.status==='sent'?'preparing':'ready'
  try { await api(`/order-items/${item.id}/status`,{method:'PATCH',body:JSON.stringify({status:next})});selectedKdsOrder.value=await api(`/orders/${selectedKdsOrder.value.id}`);await loadData();notify(next==='preparing'?'Đã bắt đầu pha món':next==='ready'?'Món đã sẵn sàng':'Đã giao món') }
  catch(error){notify(error.message)}
}
async function closeOrder(order,status) { const reason=status==='cancelled'?prompt('Lý do hủy đơn:','Khách đổi ý'):null;if(status==='cancelled'&&!reason)return;if(status==='paid'&&!confirm('Hoàn tất và lưu giao dịch này?'))return;try{await api(`/orders/${order.id}/status`,{method:'PATCH',body:JSON.stringify({status,reason})});allOrders.value=await api('/orders');await loadData();notify(status==='paid'?'Đã thanh toán và lưu lịch sử':'Đã hủy đơn')}catch(error){notify(error.message)} }
async function settleCurrent(method){if(!currentOrder.value)return;if(!confirm(method==='bank_transfer'?'Xác nhận đã nhận tiền chuyển khoản?':'Xác nhận đã nhận đủ tiền mặt?'))return;try{const paid=await api(`/orders/${currentOrder.value.id}/pay`,{method:'POST',body:JSON.stringify({method,reference:method==='bank_transfer'?`HD${currentOrder.value.orderNumber}`:null})});showReceipt.value=false;showOrder.value=false;showQr.value=false;currentOrder.value=null;await loadData();paymentSuccess.value={amount:paid.amount,method};setTimeout(()=>paymentSuccess.value=null,2600)}catch(error){notify(error.message)}}
function goOpenShift(){showReceipt.value=false;showQr.value=false;showOrder.value=false;selectView('Ca làm & đối soát')}
async function printReceipt(){showReceipt.value=true;await nextTick();const image=document.querySelector('.qr-payment img');if(image&&!image.complete)await Promise.race([new Promise(resolve=>{image.addEventListener('load',resolve,{once:true});image.addEventListener('error',resolve,{once:true})}),new Promise(resolve=>setTimeout(resolve,4000))]);window.print()}
async function savePaymentSettings(){try{paymentSettings.value=await api('/payment-settings',{method:'PUT',body:JSON.stringify(paymentSettings.value)});paymentSettingsEditing.value=false;notify('Đã lưu tài khoản nhận QR')}catch(error){notify(error.message)}}
async function loadInventory(){
  const [i,s,r,p]=await Promise.all([api('/inventory/ingredients'),api('/inventory/suppliers'),api('/inventory/receipts'),api('/inventory/report')])
  ingredients.value=i;suppliers.value=s;stockReceipts.value=r;inventoryReport.value=p
  for(const item of i)if(physicalCounts.value[item.id]===undefined)physicalCounts.value[item.id]=item.quantity
}
async function createIngredient(){try{await api('/inventory/ingredients',{method:'POST',body:JSON.stringify({...newIngredient.value,reorderLevel:Number(newIngredient.value.reorderLevel)})});newIngredient.value={code:'',name:'',category:'',unit:'g',reorderLevel:0};await loadInventory();notify('Đã thêm nguyên liệu')}catch(error){notify(error.message)}}
async function createSupplier(){try{await api('/inventory/suppliers',{method:'POST',body:JSON.stringify(newSupplier.value)});newSupplier.value={name:'',phone:'',address:'',note:''};await loadInventory();notify('Đã thêm nhà cung cấp')}catch(error){notify(error.message)}}
function addReceiptLine(){receiptForm.value.items.push({ingredientId:'',quantity:1,unitCost:0})}
function removeReceiptLine(index){if(receiptForm.value.items.length>1)receiptForm.value.items.splice(index,1)}
async function createStockReceipt(){try{const items=receiptForm.value.items.filter(i=>i.ingredientId).map(i=>({...i,quantity:Number(i.quantity),unitCost:Number(i.unitCost)}));await api('/inventory/receipts',{method:'POST',body:JSON.stringify({...receiptForm.value,supplierId:receiptForm.value.supplierId||null,items})});receiptForm.value={supplierId:'',note:'',items:[{ingredientId:'',quantity:1,unitCost:0}]};await loadInventory();notify('Đã tạo phiếu nhập nháp')}catch(error){notify(error.message)}}
async function confirmReceipt(item){if(!confirm(`Xác nhận phiếu nhập #${item.receiptNumber}? Tồn kho sẽ được cộng ngay.`))return;try{await api(`/inventory/receipts/${item.id}/confirm`,{method:'POST'});await loadInventory();notify('Đã nhập kho')}catch(error){notify(error.message)}}
async function adjustStock(){try{await api('/inventory/adjustments',{method:'POST',body:JSON.stringify({...adjustmentForm.value,quantityChange:Number(adjustmentForm.value.quantityChange)})});adjustmentForm.value={ingredientId:'',quantityChange:'',reason:''};await loadInventory();notify('Đã ghi nhận điều chỉnh kho')}catch(error){notify(error.message)}}
async function saveInventoryCount(){if(!confirm('Chốt kiểm kê và cập nhật tồn thực tế?'))return;try{await api('/inventory/counts',{method:'POST',body:JSON.stringify({note:countNote.value,items:ingredients.value.map(i=>({ingredientId:i.id,actualQuantity:Number(physicalCounts.value[i.id])}))})});countNote.value='';await loadInventory();notify('Đã chốt kiểm kê')}catch(error){notify(error.message)}}
function addRecipeLine(){recipeItems.value.push({ingredientId:'',quantity:1})}
async function loadRecipe(){if(!recipeOwner.value.id)return;try{const rows=await api(`/inventory/recipes/${recipeOwner.value.kind}/${recipeOwner.value.id}`);recipeItems.value=rows.length?rows.map(x=>({ingredientId:x.ingredientId,quantity:x.quantity})):[{ingredientId:'',quantity:1}]}catch(error){notify(error.message)}}
async function saveRecipe(){if(!recipeOwner.value.id)return notify('Hãy chọn món hoặc topping');try{await api(`/inventory/recipes/${recipeOwner.value.kind}/${recipeOwner.value.id}`,{method:'PUT',body:JSON.stringify({items:recipeItems.value.filter(i=>i.ingredientId).map(i=>({...i,quantity:Number(i.quantity)}))})});await loadInventory();notify('Đã lưu định lượng món')}catch(error){notify(error.message)}}
async function createUser(){try{await api('/users',{method:'POST',body:JSON.stringify(newUser.value)});newUser.value={name:'',email:'',password:'',role:'server'};users.value=await api('/users');notify('Đã tạo tài khoản nhân viên')}catch(error){notify(error.message)}
}
async function submitOrder() {
  if (!cart.value.length) return
  if (token.value) {
    try { const table = tables.value.find(t => t.name === selectedTable.value); await api('/orders', { method:'POST', body:JSON.stringify({ tableId:table.Id || table.id, items:cart.value.map(item => ({ productId:item.id, quantity:item.qty, note:item.note?.trim() || null, toppings:item.selectedToppings.map(toppingId=>({toppingId})) })) }) }); cart.value=[];showOrder.value=false;await loadData();notify(`Đã gửi đơn ${selectedTable.value} đến KDS`);return }
    catch (error) { toast.value = error.message; setTimeout(() => toast.value='', 2800); return }
  }
  orders.value.unshift({ id: '#1087', table: selectedTable.value, items: `${cart.value.reduce((n, x) => n + x.qty, 0)} món`, time: 'Bây giờ', state: 'Chờ pha', color: 'purple' })
  const t = tables.value.find(t => t.name === selectedTable.value)
  if (t) { t.status = 'Đang dùng'; t.time = 'Vừa mở'; t.tone = 'busy'; t.bill = formattedTotal.value }
  cart.value = []; showOrder.value = false; toast.value = `Đã gửi đơn ${selectedTable.value} đến KDS`
  setTimeout(() => toast.value = '', 2800)
}
</script>

<template>
  <main class="app-shell" :class="['role-' + (currentUser?.role || 'guest'), {'menu-open':sidebarOpen}]">
    <div v-if="licenseStatus && !licenseStatus.allowed" class="login-screen license-screen">
      <form class="login-card license-card" @submit.prevent="activateLicense"><div class="brand"><span class="brand-mark">R</span><span>ROAST<br><i>& ROOT</i></span></div><p class="eyebrow">KÍCH HOẠT COFFEE OS</p><h2>Thời hạn sử dụng đã hết</h2><p>{{ licenseStatus.message }}</p><label>Mã máy<div class="installation-id"><code>{{ licenseStatus.installationId }}</code><button type="button" @click="copyInstallationId">Sao chép</button></div></label><label>Key bản quyền<textarea v-model="licenseKey" rows="5" placeholder="Dán key do nhà cung cấp gửi" required></textarea></label><small v-if="licenseError" class="login-error">{{ licenseError }}</small><button class="send-order" :disabled="activatingLicense">{{ activatingLicense ? 'Đang kiểm tra...' : 'Kích hoạt →' }}</button><small class="license-help">Gửi mã máy cho nhà cung cấp để nhận key. Key của máy khác sẽ không sử dụng được.</small></form>
    </div>
    <div v-else-if="!token" class="login-screen">
      <form class="login-card" @submit.prevent="login"><div class="brand"><span class="brand-mark">R</span><span>ROAST<br><i>& ROOT</i></span></div><p class="eyebrow">COFFEE OPERATING SYSTEM</p><h2>Chào mừng trở lại</h2><p>Đăng nhập để làm việc với dữ liệu cửa hàng.</p><label>Email<input v-model="loginForm.email" type="email" placeholder="owner@tenquan.vn" required></label><label>Mật khẩu<input v-model="loginForm.password" type="password" placeholder="••••••••" required></label><small v-if="loginError" class="login-error">{{ loginError }}</small><button class="send-order" :disabled="signingIn">{{ signingIn ? 'Đang đăng nhập...' : 'Đăng nhập →' }}</button></form>
    </div>
    <button v-if="token && sidebarOpen" class="sidebar-overlay" aria-label="Đóng menu" @click="sidebarOpen=false"></button>
    <aside v-if="token" class="sidebar" :class="{open:sidebarOpen}">
      <button class="sidebar-close" aria-label="Đóng menu" @click="sidebarOpen=false">×</button>
      <div class="brand"><span class="brand-mark">R</span><span>ROAST<br><i>& ROOT</i></span></div>
      <nav><p>VẬN HÀNH</p><button v-for="item in operationalNav" :key="item" :class="{ active: activeView === item }" @click="selectView(item)"><span>{{ item === 'Tổng quan' ? '◌' : item === 'Sơ đồ bàn' ? '▦' : item === 'Đơn hàng' ? '◫' : '◈' }}</span>{{ item }}<em v-if="item === 'Pha chế · KDS'">{{ orders.length }}</em></button><template v-if="managementNav.length"><p>QUẢN LÝ</p><button v-for="item in managementNav" :key="item" :class="{ active: activeView === item }" @click="selectView(item)"><span>◇</span>{{ item }}</button></template></nav>
      <div class="profile"><div class="avatar">{{ userInitials }}</div><div><b>{{ currentUser?.name }}</b><small>{{ roleNames[currentUser?.role] || currentUser?.role }}</small></div><button class="logout" title="Đăng xuất" @click="logout">↪ <span class="logout-label">Đăng xuất</span></button></div>
    </aside>

    <section v-if="token" class="workspace">
      <header><button class="mobile-menu" aria-label="Mở menu" @click="sidebarOpen=true"><span></span><span></span><span></span></button><div class="page-heading"><p class="eyebrow">HỆ THỐNG VẬN HÀNH</p><h1>{{ activeView }}</h1></div><div class="header-actions"><button v-if="['owner','manager','cashier','server'].includes(currentUser?.role)" class="new-order" @click="openNewOrder">＋ Tạo đơn mới</button></div></header>
      <div v-if="activeView === 'Tổng quan'" class="metrics"><div><span>DOANH THU HÔM NAY</span><strong>{{ new Intl.NumberFormat('vi-VN').format(report.revenue) }}đ</strong><small>Dữ liệu từ giao dịch thật</small></div><div><span>ĐƠN ĐANG PHỤC VỤ</span><strong>{{ allOrders.filter(o=>!['paid','cancelled'].includes(o.status)).length }} <i>đơn</i></strong><small>Đơn chưa thanh toán</small></div><div><span>TỔNG SỐ BÀN</span><strong>{{ tables.length }} <i>bàn</i></strong><small>{{ tables.filter(t => t.tone === 'free').length }} bàn trống</small></div><div><span>MENU ĐANG BÁN</span><strong>{{ menu.length }} <i>món</i></strong><small>Dữ liệu SQL Server</small></div></div>
      <template v-if="activeView === 'Sơ đồ bàn' || activeView === 'Tổng quan'">
        <div class="area-toolbar"><div class="area-tabs"><button v-for="area in areas" :key="area.id" :class="{active:selectedAreaId===area.id}" @click="selectedAreaId=area.id;newTable.areaId=area.id;layoutSelectedTable=null">{{ area.name }} <small>{{ area.tableCount }}</small></button></div><button v-if="['owner','manager'].includes(currentUser?.role)" class="add-area-btn" @click="showAreaForm=!showAreaForm">＋ Khu vực</button></div>
        <form v-if="showAreaForm" class="panel-card area-form" @submit.prevent="createArea"><input v-model="newArea.name" placeholder="Tên khu vực, ví dụ Sân vườn" required><label>Rộng <input v-model="newArea.canvasWidth" type="number" min="500" max="2400"></label><label>Cao <input v-model="newArea.canvasHeight" type="number" min="400" max="1600"></label><button class="new-order">Tạo khu vực</button></form>
        <section class="floor-head"><div><h2>{{ activeArea?.name || 'Khu vực' }} <span>{{ areaTables.length }} bàn</span></h2><p>{{ layoutEditing ? 'Kéo bàn để di chuyển; chọn bàn để đổi kiểu và kích thước' : 'Chạm vào bàn để xem chi tiết, gọi thêm hoặc tính tiền' }}</p></div><div class="floor-tools"><button v-if="['owner','manager'].includes(currentUser?.role)" class="notice-enable" @click="layoutEditing=!layoutEditing;layoutSelectedTable=null">{{ layoutEditing ? '✓ Hoàn tất chỉnh sơ đồ' : '✥ Chỉnh sơ đồ' }}</button><button class="new-order" @click="showTableForm=!showTableForm">＋ Thêm bàn</button></div></section>
        <form v-if="showTableForm" class="panel-card table-form advanced-table-form" @submit.prevent="createTable"><input v-model="newTable.name" placeholder="Tên bàn, ví dụ Bàn 01" required><input v-model="newTable.seats" type="number" min="1" max="30" placeholder="Số ghế" required><select v-model="newTable.areaId" required><option v-for="area in areas" :key="area.id" :value="area.id">{{ area.name }}</option></select><select v-model="newTable.shape"><option value="rectangle">Chữ nhật</option><option value="round">Tròn</option><option value="square">Vuông</option></select><button class="new-order">Lưu bàn</button></form>
        <section class="content-grid"><div class="floor" :class="{'layout-editing':layoutEditing}" :style="areaCanvasStyle()" @dragover.prevent @drop="dropTable"><div v-for="(table,index) in areaTables" :key="table.name" class="table-card" :draggable="layoutEditing" :style="tableStyle(table,index)" @dragstart="beginTableDrag($event,table)" :class="[table.tone,'shape-'+(table.shape||'rectangle'),{selected:selectedTable===table.name,'layout-selected':layoutSelectedTable==table}]" @click="layoutEditing ? selectLayoutTable(table) : openTable(table)"><div class="table-top"><b>{{ table.name }}</b><span>♟ {{ table.seats }}</span></div><div class="table-middle"><i></i><i></i></div><div class="table-info"><strong>{{ table.status }}</strong><span v-if="table.time">{{ table.time }}</span><small v-if="table.bill">{{ table.bill }}</small></div></div><p v-if="!areaTables.length" class="empty">Khu vực này chưa có bàn.</p><div class="window-label">SƠ ĐỒ {{ activeArea?.name?.toUpperCase() }}</div><div v-if="layoutEditing" class="layout-inspector" @click.stop><h3>Thiết lập sơ đồ</h3><label>Tên khu vực<input v-model="activeArea.name"></label><div class="inspector-pair"><label>Rộng<input v-model.number="activeArea.canvasWidth" type="number" min="500" max="2400"></label><label>Cao<input v-model.number="activeArea.canvasHeight" type="number" min="400" max="1600"></label></div><div class="inspector-actions"><button @click="saveArea">Lưu khu vực</button><button class="danger" @click="deleteArea">Xóa</button></div><template v-if="layoutSelectedTable"><hr><h3>{{ layoutSelectedTable.name }}</h3><label>Chuyển khu vực<select v-model="layoutSelectedTable.areaId"><option v-for="area in areas" :key="area.id" :value="area.id">{{ area.name }}</option></select></label><label>Kiểu bàn<select v-model="layoutSelectedTable.shape"><option value="rectangle">Chữ nhật</option><option value="round">Tròn</option><option value="square">Vuông</option></select></label><div class="inspector-pair"><label>Rộng<input v-model.number="layoutSelectedTable.width" type="number" min="90" max="360"></label><label>Cao<input v-model.number="layoutSelectedTable.height" type="number" min="80" max="260"></label></div><button class="save-layout" @click="saveTableLayout()">Lưu bàn</button></template></div></div><aside class="kds"><div class="kds-title"><div><p>PHA CHẾ · KDS</p><h2>Đơn cần xử lý</h2></div><span>{{ orders.length }}</span></div><div v-for="order in orders" :key="order.id" class="order-card clickable" @click="openKdsOrder(order)"><div><b>{{ order.table }}</b><span>{{ order.id }} · {{ order.time }}</span></div><p>{{ order.items }} · Bấm để xem món</p><button :class="order.color" :disabled="!canAdvanceOrder(order)" @click.stop="advanceOrder(order)">{{ orderActionLabel(order) }} <i v-if="canAdvanceOrder(order)">→</i></button></div><button class="view-kds" @click="selectView('Pha chế · KDS')">Mở màn hình pha chế →</button></aside></section>
      </template>
      <section v-else-if="activeView === 'Phục vụ bàn'" class="service-view"><div class="service-heading"><div><p class="eyebrow">DÀNH CHO NHÂN VIÊN PHỤC VỤ</p><h2>Gọi món và theo dõi tiến độ</h2><span>Chọn bàn để tạo đơn hoặc gọi thêm món cho khách.</span></div><div class="service-heading-actions"><button class="notice-enable" @click="enableNotifications">{{ notificationsEnabled ? '✓ Đã bật báo món' : '🔔 Bật báo món' }}</button><button class="new-order" @click="openNewOrder">＋ Chọn bàn gọi món</button></div></div><div class="service-grid"><div class="panel-card"><h2>Bàn phục vụ <span>{{ tables.length }} bàn</span></h2><div class="service-table-grid"><button v-for="table in tables" :key="table.name" :class="table.tone" @click="openTable(table)"><b>{{ table.name }}</b><span>{{ table.status }}</span><small>{{ table.tone === 'free' ? 'Nhận khách & gọi món' : table.tone === 'payment-requested' ? 'Đã gọi thu ngân' : 'Xem đơn / gọi thêm' }}</small></button></div></div><div class="panel-card service-progress"><h2>Tiến độ món</h2><p v-if="!allOrders.filter(o=>!['paid','cancelled'].includes(o.status)).length" class="empty">Chưa có bàn đang phục vụ.</p><div v-for="order in allOrders.filter(o=>!['paid','cancelled'].includes(o.status))" :key="order.id" class="service-order"><button class="service-order-main" @click="openKdsOrder({id:order.id})"><div><b>#{{ order.orderNumber }} · {{ order.tableName }}</b><small>{{ order.itemCount }} món · {{ new Date(order.openedAt).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}) }}</small></div><span :class="'status-'+order.status">{{ itemStatusNames[order.status] || order.status }}</span></button><button class="bill-request-btn" :disabled="!!order.billRequestedAt" @click="requestBill(order)">{{ order.billRequestedAt ? '✓ Đã gọi tính tiền' : 'Yêu cầu in bill' }}</button></div></div></div></section>
      <section v-else-if="activeView === 'Thu ngân POS'" class="pos-view"><div class="pos-summary"><div><span>CHỜ THANH TOÁN</span><strong>{{ allOrders.filter(o=>o.billRequestedAt&&!['paid','cancelled'].includes(o.status)).length }}</strong></div><div><span>ĐƠN ĐANG MỞ</span><strong>{{ allOrders.filter(o=>!['paid','cancelled'].includes(o.status)).length }}</strong></div><div><span>CA HIỆN TẠI</span><strong>{{ currentShift ? 'Đang mở' : 'Chưa mở' }}</strong></div></div><div class="panel-card"><h2>Yêu cầu từ phục vụ</h2><p v-if="!allOrders.some(o=>o.billRequestedAt&&!['paid','cancelled'].includes(o.status))" class="empty">Chưa có yêu cầu thanh toán.</p><button v-for="order in allOrders.filter(o=>o.billRequestedAt&&!['paid','cancelled'].includes(o.status))" :key="order.id" class="pos-order" @click="openOrderAtTable(order)"><div><b>#{{ order.orderNumber }} · {{ order.tableName }}</b><small>{{ order.itemCount }} món · yêu cầu {{ new Date(order.billRequestedAt).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'}) }}</small></div><strong>{{ new Intl.NumberFormat('vi-VN').format(order.total) }}đ</strong><span>Mở thanh toán →</span></button></div><div class="panel-card"><h2>Tất cả đơn đang mở</h2><p v-if="!allOrders.some(o=>!['paid','cancelled'].includes(o.status))" class="empty">Không có đơn đang mở.</p><button v-for="order in allOrders.filter(o=>!['paid','cancelled'].includes(o.status))" :key="order.id" class="pos-order" @click="openOrderAtTable(order)"><div><b>#{{ order.orderNumber }} · {{ order.tableName }}</b><small>{{ order.itemCount }} món · {{ itemStatusNames[order.status] || order.status }}</small></div><strong>{{ new Intl.NumberFormat('vi-VN').format(order.total) }}đ</strong><span>Xem / thu tiền →</span></button></div><div class="panel-card printer-card"><h2>Máy in bill & két tiền</h2><form class="printer-form" @submit.prevent="savePrinterSettings"><input v-model="printerSettings.printerName" placeholder="Tên máy in trong Windows, ví dụ POS-80"><label><input v-model="printerSettings.autoPrint" type="checkbox"> Tự động in bill</label><label><input v-model="printerSettings.openCashDrawer" type="checkbox"> Mở két khi thu tiền</label><button class="new-order">Lưu cấu hình</button><button type="button" @click="testPrinter">In thử</button><button type="button" @click="openCashDrawer">Mở két thử</button></form></div></section>
      <section v-else-if="activeView === 'Ca làm & đối soát'" class="admin-panel shift-view">
        <div class="panel-card"><h2>{{ currentShift ? 'Ca đang hoạt động' : 'Mở ca thu ngân' }}</h2>
          <template v-if="currentShift"><p class="shift-period">Tính từ <b>{{ formatReceiptDate(currentShift.openedAt) }}</b> đến thời điểm hiện tại · tự cập nhật mỗi 2 giây</p><div class="shift-live-grid"><div><span>TIỀN ĐẦU CA</span><strong>{{ new Intl.NumberFormat('vi-VN').format(currentShift.openingCash) }}đ</strong></div><div><span>THU TIỀN MẶT</span><strong>{{ new Intl.NumberFormat('vi-VN').format(currentShift.cashSales) }}đ</strong></div><div><span>CHUYỂN KHOẢN / THẺ</span><strong>{{ new Intl.NumberFormat('vi-VN').format(currentShift.nonCashSales) }}đ</strong></div><div><span>TỔNG DOANH THU CA</span><strong>{{ new Intl.NumberFormat('vi-VN').format(currentShift.totalSales) }}đ</strong><small>{{ currentShift.transactionCount }} giao dịch</small></div><div class="expected"><span>TIỀN DỰ KIẾN TRONG KÉT</span><strong>{{ new Intl.NumberFormat('vi-VN').format(currentShift.expectedCash) }}đ</strong><small>Tiền đầu ca + thanh toán tiền mặt</small></div></div></template>
          <form class="shift-close-form" @submit.prevent="currentShift ? closeShift() : openShift()"><label><span>{{ currentShift ? 'Tiền mặt thực tế đếm trong két' : 'Tiền mặt đầu ca' }}</span><input v-model="shiftCash" type="number" min="0" :placeholder="currentShift ? 'Nhập số tiền đã đếm' : 'Ví dụ: 1.000.000'" required></label><div v-if="currentShift && shiftCash!==''" class="variance-preview" :class="{negative:Number(shiftCash)!==currentShift.expectedCash}"><span>Chênh lệch tạm tính</span><strong>{{ new Intl.NumberFormat('vi-VN').format(Number(shiftCash)-currentShift.expectedCash) }}đ</strong></div><button class="new-order">{{ currentShift ? 'Kết ca & lưu đối soát' : 'Mở ca' }}</button></form>
        </div>
        <div class="panel-card"><h2>Lịch sử đối soát</h2><p v-if="!shiftHistory.length" class="empty">Chưa có ca nào.</p><div v-for="row in shiftHistory" :key="row.id" class="shift-history-row"><div><b>{{ row.staff }}</b><small>{{ formatReceiptDate(row.openedAt) }} <template v-if="row.closedAt">→ {{ formatReceiptDate(row.closedAt) }}</template></small></div><span>{{ row.transactionCount }} giao dịch<br><small>Doanh thu {{ new Intl.NumberFormat('vi-VN').format(row.totalSales) }}đ</small></span><span>Tiền mặt {{ new Intl.NumberFormat('vi-VN').format(row.cashSales) }}đ<br><small>Không tiền mặt {{ new Intl.NumberFormat('vi-VN').format(row.nonCashSales) }}đ</small></span><strong v-if="row.status==='closed'" :class="{negative:row.variance!==0}">Lệch {{ new Intl.NumberFormat('vi-VN').format(row.variance) }}đ</strong><em v-else>Đang mở</em></div></div>
      </section>
      <section v-else-if="activeView === 'Khuyến mãi & khách hàng'" class="admin-panel"><div class="panel-card"><h2>Tạo mã khuyến mãi</h2><form class="promo-form" @submit.prevent="createPromotion"><input v-model="newPromotion.code" placeholder="Mã" required><input v-model="newPromotion.name" placeholder="Tên chương trình" required><select v-model="newPromotion.type"><option value="percent">Giảm phần trăm</option><option value="fixed">Giảm số tiền</option></select><input v-model="newPromotion.value" type="number" min="1" placeholder="Giá trị" required><input v-model="newPromotion.minimumOrder" type="number" min="0" placeholder="Đơn tối thiểu"><input v-model="newPromotion.maximumDiscount" type="number" min="0" placeholder="Giảm tối đa"><button class="new-order">Tạo mã</button></form></div><div class="panel-card"><h2>Khuyến mãi hiện có</h2><div v-for="promo in promotions" :key="promo.id" class="data-row"><b>{{ promo.code }}<small>{{ promo.name }}</small></b><span>{{ promo.type==='percent' ? promo.value+'%' : new Intl.NumberFormat('vi-VN').format(promo.value)+'đ' }}</span><em>{{ promo.isActive ? 'Đang dùng' : 'Đã tắt' }}</em></div></div><div class="panel-card"><h2>Khách hàng thân thiết <span>{{ customers.length }} khách</span></h2><div v-for="customer in customers" :key="customer.id" class="data-row"><b>{{ customer.name }}<small>{{ customer.phone }}</small></b><span>{{ customer.points }} điểm</span><strong>{{ new Intl.NumberFormat('vi-VN').format(customer.totalSpent) }}đ</strong></div></div></section>
      <section v-else-if="activeView === 'Kho nguyên liệu'" class="admin-panel inventory-view">
        <div class="inventory-metrics"><div><span>GIÁ TRỊ TỒN KHO</span><strong>{{ new Intl.NumberFormat('vi-VN').format(inventoryReport.summary.stockValue) }}đ</strong></div><div :class="{warning:inventoryReport.summary.lowStockCount}"><span>SẮP / ĐÃ HẾT</span><strong>{{ inventoryReport.summary.lowStockCount }}</strong></div><div><span>GIÁ VỐN ĐÃ DÙNG</span><strong>{{ new Intl.NumberFormat('vi-VN').format(inventoryReport.costs.consumptionCost) }}đ</strong></div><div><span>HAO HỤT</span><strong>{{ new Intl.NumberFormat('vi-VN').format(inventoryReport.costs.wasteCost) }}đ</strong></div></div>
        <div class="panel-card"><h2>Nguyên liệu <span>{{ ingredients.length }} loại</span></h2><form class="inventory-form five" @submit.prevent="createIngredient"><input v-model="newIngredient.code" placeholder="Mã, VD: CF01"><input v-model="newIngredient.name" placeholder="Tên nguyên liệu" required><input v-model="newIngredient.category" placeholder="Nhóm"><input v-model="newIngredient.unit" placeholder="Đơn vị: g, ml..." required><input v-model="newIngredient.reorderLevel" type="number" min="0" step="0.001" placeholder="Mức cảnh báo"><button class="new-order">Thêm nguyên liệu</button></form><div class="inventory-table"><div class="inventory-head"><b>Nguyên liệu</b><b>Tồn</b><b>Giá vốn TB</b><b>Ảnh hưởng món</b></div><div v-for="item in ingredients" :key="item.id" class="inventory-row" :class="{low:item.lowStock}"><b>{{ item.name }}<small>{{ item.code || 'Chưa có mã' }} · {{ item.category || 'Chưa phân nhóm' }}</small></b><span>{{ item.quantity }} {{ item.unit }}<em v-if="item.lowStock">Sắp hết</em></span><span>{{ new Intl.NumberFormat('vi-VN').format(item.averageCost) }}đ/{{ item.unit }}</span><small>{{ item.affectedProducts || 'Chưa gắn định lượng' }}</small></div></div></div>
        <div class="inventory-columns"><div class="panel-card"><h2>Nhà cung cấp</h2><form class="inventory-form" @submit.prevent="createSupplier"><input v-model="newSupplier.name" placeholder="Tên nhà cung cấp" required><input v-model="newSupplier.phone" placeholder="Điện thoại"><input v-model="newSupplier.address" placeholder="Địa chỉ"><button class="new-order">Thêm</button></form><div v-for="item in suppliers" :key="item.id" class="data-row"><b>{{ item.name }}<small>{{ item.address }}</small></b><span>{{ item.phone }}</span></div></div><div class="panel-card"><h2>Điều chỉnh kho</h2><form class="inventory-form" @submit.prevent="adjustStock"><select v-model="adjustmentForm.ingredientId" required><option value="" disabled>Chọn nguyên liệu</option><option v-for="i in ingredients" :key="i.id" :value="i.id">{{ i.name }}</option></select><input v-model="adjustmentForm.quantityChange" type="number" step="0.001" placeholder="+ nhập / − hao hụt" required><input v-model="adjustmentForm.reason" placeholder="Lý do" required><button class="new-order">Ghi nhận</button></form></div></div>
        <div class="panel-card"><h2>Tạo phiếu nhập kho</h2><div class="receipt-base"><select v-model="receiptForm.supplierId"><option value="">Không chọn nhà cung cấp</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select><input v-model="receiptForm.note" placeholder="Ghi chú / số hóa đơn NCC"><button @click="addReceiptLine">＋ Thêm dòng</button></div><div v-for="(line,index) in receiptForm.items" :key="index" class="receipt-line"><select v-model="line.ingredientId" required><option value="" disabled>Nguyên liệu</option><option v-for="i in ingredients" :key="i.id" :value="i.id">{{ i.name }} ({{ i.unit }})</option></select><input v-model="line.quantity" type="number" min="0.001" step="0.001" placeholder="Số lượng"><input v-model="line.unitCost" type="number" min="0" step="0.01" placeholder="Đơn giá / đơn vị"><strong>{{ new Intl.NumberFormat('vi-VN').format(Number(line.quantity||0)*Number(line.unitCost||0)) }}đ</strong><button class="danger-btn" @click="removeReceiptLine(index)">Xóa</button></div><button class="new-order inventory-submit" @click="createStockReceipt">Lưu phiếu nhập nháp</button></div>
        <div class="panel-card"><h2>Phiếu nhập gần đây</h2><div v-for="item in stockReceipts" :key="item.id" class="stock-receipt"><b>#{{ item.receiptNumber }} · {{ item.supplier }}<small>{{ new Date(item.createdAt).toLocaleString('vi-VN') }} · {{ item.itemCount }} dòng</small></b><strong>{{ new Intl.NumberFormat('vi-VN').format(item.totalCost) }}đ</strong><em :class="item.status">{{ item.status==='confirmed'?'Đã nhập kho':'Bản nháp' }}</em><button v-if="item.status==='draft'" class="new-order" @click="confirmReceipt(item)">Xác nhận nhập</button></div></div>
        <div class="inventory-columns"><div class="panel-card"><h2>Định lượng món / topping</h2><div class="recipe-owner"><select v-model="recipeOwner.kind" @change="recipeOwner.id='';recipeItems=[]"><option value="product">Món</option><option value="topping">Topping</option></select><select v-model="recipeOwner.id" @change="loadRecipe"><option value="" disabled>Chọn để sửa công thức</option><option v-for="x in recipeOwner.kind==='product'?menu:toppings" :key="x.id" :value="x.id">{{ x.name }}</option></select><button @click="addRecipeLine">＋ Nguyên liệu</button></div><div v-for="(line,index) in recipeItems" :key="index" class="recipe-line"><select v-model="line.ingredientId"><option value="" disabled>Nguyên liệu</option><option v-for="i in ingredients" :key="i.id" :value="i.id">{{ i.name }} ({{ i.unit }})</option></select><input v-model="line.quantity" type="number" min="0.001" step="0.001" placeholder="Lượng / món"><button class="danger-btn" @click="recipeItems.splice(index,1)">×</button></div><button class="new-order inventory-submit" @click="saveRecipe">Lưu định lượng</button></div><div class="panel-card"><h2>Kiểm kê thực tế</h2><input v-model="countNote" class="count-note" placeholder="Ghi chú phiên kiểm kê"><div class="count-grid"><label v-for="i in ingredients" :key="i.id"><span>{{ i.name }} <small>({{ i.unit }})</small></span><input v-model="physicalCounts[i.id]" type="number" min="0" step="0.001"></label></div><button class="new-order inventory-submit" @click="saveInventoryCount">Chốt kiểm kê</button></div></div>
        <div class="panel-card"><h2>Nhật ký xuất nhập kho</h2><div v-for="m in inventoryReport.movements" :key="m.id" class="movement-row"><b>{{ m.ingredient }}<small>{{ m.reason }}</small></b><strong :class="{negative:m.quantityChange<0}">{{ m.quantityChange>0?'+':'' }}{{ m.quantityChange }} {{ m.unit }}</strong><span>Còn {{ m.balanceAfter ?? '—' }}</span><small>{{ m.staff }} · {{ new Date(m.createdAt).toLocaleString('vi-VN') }}</small></div></div>
      </section>
      <section v-else-if="activeView === 'Menu & danh mục'" class="admin-panel"><div class="panel-card"><h2>Thêm món mới</h2><form class="inline-form" @submit.prevent="createProduct"><input v-model="newProduct.name" placeholder="Tên món" required><input v-model="newProduct.price" type="number" min="0" placeholder="Giá bán" required><button class="new-order">Thêm món</button></form></div><div class="panel-card"><h2>Menu hiện tại <span>{{ menu.length }} món</span></h2><div v-for="item in menu" :key="item.id || item.name" class="data-row"><span>{{ item.emoji }}</span><b>{{ item.name }}</b><strong>{{ new Intl.NumberFormat('vi-VN').format(item.price) }}đ</strong><button class="danger-btn" @click="deleteProduct(item)">Xóa</button></div></div><div class="panel-card"><h2>Topping và giá bán</h2><form class="topping-form" @submit.prevent="createTopping"><select v-model="newTopping.productId" required><option value="" disabled>Chọn món áp dụng</option><option v-for="item in menu" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model="newTopping.name" placeholder="Tên topping" required><input v-model="newTopping.price" type="number" min="0" placeholder="Giá" required><button class="new-order">Thêm topping</button></form><div v-for="topping in toppings" :key="topping.id" class="data-row"><b>{{ menu.find(m=>m.id===topping.productId)?.name }}</b><span>{{ topping.name }}</span><strong>{{ new Intl.NumberFormat('vi-VN').format(topping.price) }}đ</strong><button class="danger-btn" @click="deleteTopping(topping)">Xóa</button></div></div></section>
      <section v-else-if="activeView === 'Pha chế · KDS'" class="admin-panel kds-panel"><div class="panel-card"><h2>Đơn đang pha chế</h2><p v-if="!orders.length" class="empty">Không còn đơn cần xử lý.</p><div v-for="order in orders" :key="order.id" class="data-row"><div><b>{{ order.id }} · {{ order.table }}</b><small>{{ order.items }} · {{ order.time }}</small></div><button class="detail-btn" @click="openKdsOrder(order)">Xem món</button><button :class="order.color" :disabled="!canAdvanceOrder(order)" @click="advanceOrder(order)">{{ orderActionLabel(order) }} <span v-if="canAdvanceOrder(order)">→</span></button></div></div><div class="panel-card availability-panel"><h2>Tình trạng món <span>Barista có thể báo hết tạm thời</span></h2><div class="availability-grid"><button v-for="item in menu" :key="item.id" :class="{soldout:!item.isAvailable}" @click="toggleAvailability(item)"><b>{{ item.name }}</b><span>{{ item.isAvailable ? 'Đang bán' : 'Tạm hết' }}</span></button></div></div></section>
      <section v-else-if="activeView === 'Đơn hàng'" class="admin-panel"><div class="panel-card"><h2>Lịch sử đơn hàng</h2><p v-if="!allOrders.length" class="empty">Chưa có đơn hàng nào.</p><div v-for="order in allOrders" :key="order.id" class="history-row"><div><b>#{{ order.orderNumber }} · {{ order.tableName }}</b><small>{{ new Date(order.openedAt).toLocaleString('vi-VN') }}</small></div><span>{{ order.itemCount }} món</span><strong>{{ new Intl.NumberFormat('vi-VN').format(order.total) }}đ</strong><em>{{ itemStatusNames[order.status] || order.status }}</em><div class="row-actions"><button @click="openKdsOrder({id:order.id})">Xem chi tiết</button><template v-if="!['paid','cancelled'].includes(order.status)"><button @click="closeOrder(order,'paid')">Hoàn tất</button><button class="danger-btn" @click="closeOrder(order,'cancelled')">Hủy</button></template></div></div></div></section>
      <template v-else-if="activeView === 'Báo cáo doanh thu'"><section class="metrics"><div><span>DOANH THU HÔM NAY</span><strong>{{ new Intl.NumberFormat('vi-VN').format(report.revenue) }}đ</strong></div><div><span>ĐƠN ĐÃ THANH TOÁN</span><strong>{{ report.paidOrders }}</strong></div><div><span>ĐƠN ĐÃ HỦY</span><strong>{{ report.cancelledOrders }}</strong></div></section><section class="admin-panel"><div class="panel-card"><h2>Cấu hình nhận thanh toán QR</h2><form class="staff-form" @input="paymentSettingsEditing=true" @submit.prevent="savePaymentSettings"><input v-model.trim="paymentSettings.bankId" autocomplete="off" placeholder="Mã ngân hàng, ví dụ MB, VCB, ACB" required><input v-model.trim="paymentSettings.accountNumber" inputmode="numeric" autocomplete="off" placeholder="Số tài khoản" required><input v-model.trim="paymentSettings.accountName" autocomplete="off" placeholder="Tên chủ tài khoản không dấu" required><button class="new-order">Lưu cấu hình QR</button></form><small v-if="paymentSettingsEditing" class="unsaved-hint">Đang chỉnh sửa · bấm “Lưu cấu hình QR” để lưu lại</small></div><div class="panel-card"><h2>Lịch sử hủy món</h2><p v-if="!operationsReport.cancellations.length" class="empty">Chưa có món bị hủy.</p><div v-for="row in operationsReport.cancellations" :key="row.orderNumber+row.createdAt" class="report-row"><b>#{{ row.orderNumber }} · {{ row.item }}</b><span>{{ row.reason }}</span><small>{{ row.staff }} · {{ new Date(row.createdAt).toLocaleString('vi-VN') }}</small><strong>{{ new Intl.NumberFormat('vi-VN').format(row.amount) }}đ</strong></div></div><div class="panel-card"><h2>Hiệu suất nhân viên</h2><div v-for="row in operationsReport.staffPerformance" :key="row.id" class="report-row staff-performance"><b>{{ row.name }}</b><span>{{ roleNames[row.role] || row.role }}</span><small>{{ row.orders }} đơn · {{ row.preparedItems }} món pha</small><strong>Thu {{ new Intl.NumberFormat('vi-VN').format(row.receivedAmount) }}đ</strong></div></div></section></template>
      <section v-else-if="activeView === 'Nhân sự & phân quyền'" class="admin-panel"><div class="panel-card"><h2>Thêm nhân viên</h2><form class="staff-form" @submit.prevent="createUser"><input v-model="newUser.name" placeholder="Họ tên" required><input v-model="newUser.email" type="email" placeholder="Email" required><input v-model="newUser.password" type="password" minlength="8" placeholder="Mật khẩu" required><select v-model="newUser.role"><option value="manager">Quản lý</option><option value="cashier">Thu ngân</option><option value="server">Phục vụ</option><option value="barista">Pha chế</option></select><button class="new-order">Tạo tài khoản</button></form></div><div class="panel-card"><h2>Danh sách nhân sự</h2><div v-for="person in users" :key="person.id" class="data-row"><div class="avatar">{{ person.name.slice(0,2).toUpperCase() }}</div><b>{{ person.name }}<small>{{ person.email }}</small></b><span>{{ roleNames[person.role] || person.role }}</span></div></div></section>
      <section v-else class="admin-panel"><div class="panel-card"><h2>{{ activeView }}</h2><p>Chưa có dữ liệu. Module kho sẽ được nối sau khi bạn khai báo nguyên liệu và định lượng món.</p></div></section>
    </section>

    <div v-if="showTablePicker" class="modal-backdrop" @click.self="showTablePicker=false"><section class="picker-modal"><button class="close" @click="showTablePicker=false">×</button><p class="eyebrow">CHỌN BÀN PHỤC VỤ</p><h2>Tạo đơn tại bàn nào?</h2><div class="picker-grid"><button v-for="table in tables" :key="table.name" @click="chooseTable(table)"><b>{{ table.name }}</b><span>{{ table.status }}</span><small>{{ table.tone === 'free' ? 'Tạo đơn mới' : 'Gọi thêm món' }}</small></button></div></section></div>
    <div v-if="showKdsOrder && selectedKdsOrder" class="modal-backdrop" @click.self="showKdsOrder=false"><section class="kds-detail-modal"><button class="close" @click="showKdsOrder=false">×</button><p class="eyebrow">CHI TIẾT ĐƠN HÀNG</p><h2>#{{ selectedKdsOrder.orderNumber }} · {{ selectedKdsOrder.tableName }}</h2><div class="kds-detail-meta"><span>{{ new Date(selectedKdsOrder.openedAt).toLocaleString('vi-VN') }}</span><b>{{ itemStatusNames[selectedKdsOrder.status] || selectedKdsOrder.status }}</b></div><div class="kds-item" v-for="item in selectedKdsOrder.items" :key="item.id"><div class="kds-item-qty">{{ item.quantity }}×</div><div><b>{{ item.name }}</b><small v-if="item.toppings">Topping: {{ item.toppings }}</small><small v-if="item.note">Ghi chú: {{ item.note }}</small><small v-else>Không có ghi chú</small></div><span :class="'status-'+item.status">{{ itemStatusNames[item.status] || item.status }}</span><button v-if="['owner','manager','barista'].includes(currentUser?.role) && ['sent','preparing'].includes(item.status)" @click="advanceItem(item)">{{ item.status === 'sent' ? 'Bắt đầu pha' : 'Chuyển sẵn sàng' }}</button></div><div class="kds-detail-total"><span>{{ selectedKdsOrder.items.reduce((n,item)=>n+item.quantity,0) }} món</span><strong v-if="currentUser?.role !== 'barista'">Tổng: {{ new Intl.NumberFormat('vi-VN').format(selectedKdsOrder.total) }}đ</strong></div></section></div>
    <div v-if="showOrder" class="modal-backdrop" @click.self="showOrder = false"><section class="order-modal"><button class="close" @click="showOrder = false">×</button><p class="eyebrow">{{ currentOrder ? 'CHI TIẾT BÀN & GỌI THÊM' : 'TẠO ĐƠN MỚI' }}</p><h2>{{ selectedTable }} <small v-if="currentOrder">#{{ currentOrder.orderNumber }}</small></h2><div v-if="currentOrder" class="ordered-items"><div class="ordered-head"><b>Món đã gọi</b><span>Mở lúc {{ new Date(currentOrder.openedAt).toLocaleString('vi-VN') }}</span></div><div v-for="item in currentOrder.items" :key="item.id" class="ordered-row" :class="{cancelled:item.status==='cancelled'}"><span>{{ item.quantity }}×</span><div class="ordered-name"><b>{{ item.name }}</b><em v-if="item.toppings">＋ {{ item.toppings }}</em><em v-if="item.note">Ghi chú: {{ item.note }}</em></div><small :class="'status-'+item.status">{{ itemStatusNames[item.status] || item.status }}</small><strong>{{ new Intl.NumberFormat('vi-VN').format(item.price*item.quantity) }}đ</strong><button v-if="item.status==='sent' && ['owner','manager','cashier','server'].includes(currentUser?.role)" class="cancel-item-btn" @click="cancelOrderItem(item)">Hủy món</button></div><div v-if="currentUser?.role==='server'" class="service-bill-action"><button :disabled="!!currentOrder.billRequestedAt" @click="requestBill(currentOrder)">{{ currentOrder.billRequestedAt ? '✓ Đã gửi yêu cầu tính tiền' : 'Yêu cầu in bill tạm tính' }}</button></div><div class="bill-actions"><button v-if="['owner','manager','server'].includes(currentUser?.role)" @click="openTransfer">Đổi / gộp bàn</button><strong>Tổng đơn: {{ new Intl.NumberFormat('vi-VN').format(currentOrder.total) }}đ</strong><button @click="printReceipt">In bill tạm</button><button class="pay-btn" @click="showReceipt=true;showQr=false">Thanh toán</button></div></div><div class="order-body"><div><p class="menu-label">{{ currentOrder ? 'GỌI THÊM MÓN' : 'CHỌN MÓN' }}</p><div class="menu-grid"><button v-for="item in menu" :key="item.name" :class="{soldout:!item.isAvailable}" :disabled="!item.isAvailable" @click="addItem(item)"><span>{{ item.emoji }}</span><b>{{ item.name }}</b><small>{{ item.isAvailable ? new Intl.NumberFormat('vi-VN').format(item.price)+'đ' : 'Tạm hết món' }}</small></button></div></div><div class="cart"><p class="menu-label">MÓN CHUẨN BỊ GỬI</p><div v-if="!cart.length" class="empty">Chưa chọn thêm món</div><div v-for="item in cart" :key="item.name" class="cart-item"><div class="qty"><button @click="changeQty(item,-1)">−</button><span>{{ item.qty }}</span><button @click="changeQty(item,1)">＋</button></div><b>{{ item.name }}</b><strong>{{ new Intl.NumberFormat('vi-VN').format(itemUnitPrice(item) * item.qty) }}đ</strong><button class="remove-item" @click="changeQty(item,-item.qty)">×</button><div v-if="toppings.some(t=>t.productId===item.id)" class="topping-options"><label v-for="topping in toppings.filter(t=>t.productId===item.id)" :key="topping.id"><input v-model="item.selectedToppings" type="checkbox" :value="topping.id"><span>{{ topping.name }} (+{{ new Intl.NumberFormat('vi-VN').format(topping.price) }}đ)</span></label></div><input v-model="item.note" maxlength="500" class="item-note" placeholder="Ghi chú: ít đá, không đường, thêm shot..."></div><div class="cart-total"><span>Tổng món mới</span><strong>{{ formattedTotal }}</strong></div><button class="send-order" :disabled="!cart.length" @click="submitOrder">Gửi món đến pha chế →</button></div></div></section></div>
    <div v-if="showReceipt && currentOrder" class="modal-backdrop receipt-backdrop">
      <section class="receipt">
        <header class="receipt-header"><div class="receipt-mark">R</div><div><h2>ROAST &amp; ROOT</h2><small>COFFEE OPERATING SYSTEM</small></div></header>
        <div class="receipt-title">HÓA ĐƠN TẠM TÍNH</div>
        <div class="receipt-meta"><span>Bàn</span><b>{{ selectedTable }}</b><span>Số đơn</span><b>#{{ currentOrder.orderNumber }}</b><span>Thời gian</span><b>{{ formatReceiptDate(currentOrder.openedAt) }}</b></div>
        <div class="receipt-table-head"><span>SL</span><span>TÊN MÓN</span><span>THÀNH TIỀN</span></div>
        <div v-for="item in currentOrder.items.filter(i => i.status !== 'cancelled')" :key="item.id" class="receipt-row"><span>{{ item.quantity }}</span><span>{{ item.name }}<small v-if="item.toppings">+ {{ item.toppings }}</small><small v-if="item.note">Ghi chú: {{ item.note }}</small></span><strong>{{ new Intl.NumberFormat('vi-VN').format(item.price*item.quantity) }}đ</strong></div>
        <div class="receipt-tools no-print"><form @submit.prevent="applyPromotion"><input v-model="promoCode" placeholder="Mã giảm giá"><button>Áp dụng</button></form><form @submit.prevent="attachCustomer"><input v-model="customerForm.phone" placeholder="SĐT khách hàng" required><input v-model="customerForm.name" placeholder="Tên khách hàng" required><button>Tích điểm</button></form><form v-if="selectedCustomer" @submit.prevent="redeemPoints"><input v-model="redeemPointsValue" type="number" min="1" :max="selectedCustomer.points" :placeholder="'Tối đa '+selectedCustomer.points+' điểm'"><button>Đổi điểm (1 điểm = 1.000đ)</button></form></div>
        <div v-if="currentOrder.subtotal > currentOrder.total" class="receipt-summary-row"><span>Tạm tính</span><b>{{ new Intl.NumberFormat('vi-VN').format(currentOrder.subtotal) }}đ</b></div>
        <div v-if="currentOrder.subtotal > currentOrder.total" class="receipt-summary-row discount"><span>Khuyến mãi / điểm</span><b>−{{ new Intl.NumberFormat('vi-VN').format(currentOrder.subtotal-currentOrder.total) }}đ</b></div>
        <div class="receipt-total"><b>TỔNG CỘNG</b><strong>{{ new Intl.NumberFormat('vi-VN').format(currentOrder.total) }}đ</strong></div>
        <div v-if="qrUrl" class="qr-payment"><img :src="qrUrl" alt="QR thanh toán đúng số tiền của hóa đơn"><b>QUÉT MÃ THANH TOÁN {{ new Intl.NumberFormat('vi-VN').format(currentOrder.total) }}đ</b><span>{{ paymentSettings.accountName }} · {{ paymentSettings.bankId }} · {{ paymentSettings.accountNumber }}</span><small>Nội dung: HD{{ currentOrder.orderNumber }}</small></div>
        <footer class="receipt-footer"><b>CẢM ƠN QUÝ KHÁCH!</b><span>Hẹn gặp lại quý khách</span></footer>
        <p v-if="currentUser?.role==='cashier'&&!currentShift" class="shift-warning no-print">Bạn chưa mở ca nên chưa thể nhận thanh toán. <button @click="goOpenShift">Mở ca ngay</button></p>
        <div class="receipt-controls no-print"><button @click="showReceipt=false;showQr=false">Đóng</button><button @click="printReceipt">In bill 80mm có QR</button><button @click="printPhysical">In nhanh ESC/POS</button><button class="pay-btn" :disabled="currentUser?.role==='cashier'&&!currentShift" @click="settleCurrent('cash')">Tiền mặt</button><button v-if="qrUrl" class="pay-btn" :disabled="currentUser?.role==='cashier'&&!currentShift" @click="settleCurrent('bank_transfer')">Đã nhận chuyển khoản</button></div>
      </section>
    </div>
    <div v-if="showTransfer && currentOrder" class="modal-backdrop" @click.self="showTransfer=false"><section class="picker-modal transfer-modal"><button class="close" @click="showTransfer=false">×</button><p class="eyebrow">ĐỔI / GỘP BÀN</p><h2>Chuyển {{ selectedTable }}</h2><select v-model="transferTargetId"><option value="" disabled>Chọn bàn đích</option><option v-for="table in tables.filter(t=>(t.Id||t.id)!==selectedTableId)" :key="table.Id||table.id" :value="table.Id||table.id">{{ table.name }} · {{ table.status }}</option></select><label><input v-model="mergeTarget" type="checkbox"> Gộp đơn nếu bàn đích đang có khách</label><button class="send-order" :disabled="!transferTargetId" @click="transferOrder">Xác nhận chuyển bàn</button></section></div>
    <div v-if="toast" class="toast">✓ {{ toast }}</div>
    <transition name="success-pop"><div v-if="paymentSuccess" class="payment-success"><div class="success-check"><span>✓</span></div><h2>Thanh toán thành công</h2><strong>{{ new Intl.NumberFormat('vi-VN').format(paymentSuccess.amount) }}đ</strong><p>{{ paymentSuccess.method === 'bank_transfer' ? 'Đã nhận chuyển khoản' : 'Đã nhận tiền mặt' }}</p></div></transition>
  </main>
</template>
